#define MAX_EVENTS 10
struct epoll_event events[MAX_EVENTS];
struct timespec ts = {
    .tv_sec = 1,
    .tv_nsec = 500000000
}; // 1.5 seconds

sigset_t ss;
int epfd = ...; // Existing epoll fd
int ready;

sigemptyset(&ss);
sigaddset(&ss, SIGTERM);

ready = epoll_pwait2(
    epfd,
    events,
    MAX_EVENTS,
    &ts,
    &ss
);
